package com.muxigame.city;
import java.util.*;
import java.nio.charset.StandardCharsets;
import com.google.gson.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.network.chat.Component;
import net.neoforged.neoforge.network.PacketDistributor;
/** Bounded city-wide maintenance. No navigation, drops or container-content snapshots. */
public final class CityMaintenance extends SavedData {
 public static final List<String> FARM=List.of("minecraft:grass_block","minecraft:dirt","minecraft:farmland","minecraft:water","minecraft:wheat","minecraft:composter");
 public static final class Worker {public UUID city;public String role="无职业";public boolean enabled,artisan;public int perHour=30,priority=50;public List<String> blocks=new ArrayList<>();public long next,workClock;}
 public static final class Plan {public boolean enabled=true,collective;public UUID warehouse;public long nextFood,foodCredit;public int scan,foodScan,foodPlots,healthyPlots;public long repaired;public String status="尚未落成";public Set<Long> damaged=new HashSet<>(),ready=new HashSet<>();@com.google.gson.annotations.JsonAdapter(CityBlockStore.Adapter.class) public Map<Long,String> baseline=new CityBlockStore();}
 public static final class State {public long revision;public Map<UUID,Worker> workers=new LinkedHashMap<>();public Map<UUID,Plan> cities=new LinkedHashMap<>();}
 State state=new State();private final Map<UUID,ArrayList<Long>> positions=new HashMap<>();private final Map<String,BlockState> decoded=new HashMap<>();private final Map<UUID,Build> builds=new LinkedHashMap<>();private int cityCursor;
 private static final class Build {CityScanCursor cursor;long revision;Map<Long,String> blocks=new CityBlockStore();Build(long r,CityScanCursor scan){revision=r;cursor=scan;}}
 public static CityMaintenance get(MinecraftServer s){return s.overworld().getDataStorage().computeIfAbsent(new Factory<>(()->CitySaveSafety.newData(s,"city_maintenance",CityMaintenance::new),CityMaintenance::load),"city_maintenance");}
 public static CityMaintenance load(CompoundTag tag,HolderLookup.Provider lookup){var d=new CityMaintenance();if(tag.contains("Json"))d.state=CityEconomy.JSON.fromJson(new String(tag.getByteArray("Json"),StandardCharsets.UTF_8),State.class);validate(d.state);return d;}
 @Override public CompoundTag save(CompoundTag tag,HolderLookup.Provider lookup){tag.putByteArray("Json",CityEconomy.JSON.toJson(state).getBytes(StandardCharsets.UTF_8));return tag;}
 static void exact(JsonElement v){if(v.isJsonObject())v.getAsJsonObject().entrySet().forEach(e->exact(e.getValue()));else if(v.isJsonArray())v.getAsJsonArray().forEach(CityMaintenance::exact);else if(v.isJsonPrimitive()&&v.getAsJsonPrimitive().isNumber())v.getAsBigDecimal().longValueExact();}
 static void validate(State s){CityEconomy.require(s!=null&&s.revision>=0&&s.workers!=null&&s.workers.size()<=512&&s.cities!=null&&s.cities.size()<=128,"修补数据越界");for(var w:s.workers.values()){CityEconomy.require(w!=null&&w.city!=null&&List.of("无职业","农民","工匠","自定义").contains(w.role)&&w.perHour>=1&&w.perHour<=3600&&w.priority>=1&&w.priority<=100&&w.blocks!=null&&w.blocks.size()<=256&&w.next>=0,"职业参数无效");for(String id:w.blocks)CityEconomy.require(BuiltInRegistries.BLOCK.containsKey(ResourceLocation.parse(id))&&!id.equals("minecraft:air"),"修补方块无效");}for(var p:s.cities.values()){CityEconomy.require(p!=null&&p.baseline!=null&&p.damaged!=null&&p.ready!=null&&p.baseline.keySet().containsAll(p.damaged)&&p.damaged.containsAll(p.ready)&&p.nextFood>=0&&p.foodCredit>=0&&p.foodCredit<72000&&(!p.collective||p.warehouse!=null),"落成记录无效");for(String v:CityBlockStore.states(p.baseline)){CityEconomy.require(v!=null&&v.length()<1024,"方块状态过长");decode(v);}}}
 static BlockState decode(String s){try{var n=TagParser.parseTag(s);CityEconomy.require(n.contains("Name")&&BuiltInRegistries.BLOCK.containsKey(ResourceLocation.parse(n.getString("Name"))),"落成方块不存在");return NbtUtils.readBlockState(BuiltInRegistries.BLOCK.asLookup(),n);}catch(com.mojang.brigadier.exceptions.CommandSyntaxException ex){throw new IllegalArgumentException("方块状态无效",ex);}}
 static String encode(BlockState s){return NbtUtils.writeBlockState(s).toString();}
 public static boolean collective(MinecraftServer s,UUID city){var p=get(s).state.cities.get(city);return p!=null&&p.collective;}
 static boolean available(ServerLevel l,CityData.City c,UUID id){if(!c.residents.contains(id))return false;var entity=l.getEntity(id);if(entity!=null)return entity.isAlive();var simulation=CityEconomy.get(l.getServer()).state.simulation.get(c.id);var person=simulation==null?null:simulation.people.get(id);return person!=null&&person.present&&!person.retired;}

 static boolean same(BlockState a,BlockState b){if(a.getBlock()!=b.getBlock())return false;if(a.getBlock() instanceof CropBlock||a.is(Blocks.WATER)||a.is(Blocks.FARMLAND)||a.is(Blocks.COMPOSTER))return true;return a.equals(b);}
 static boolean matches(Worker w,String id,Set<String> assigned){return w.blocks.contains(id)||(w.artisan&&!assigned.contains(id));}
 void start(MinecraftServer s,CityData.City c){CityEconomy.require(!builds.containsKey(c.id),"正在记录，请等待");var l=CityEconomy.level(s,c);if(c.bounds.smallSelection())for(int x=c.bounds.min().getX()>>4;x<=c.bounds.max().getX()>>4;x++)for(int z=c.bounds.min().getZ()>>4;z<=c.bounds.max().getZ()>>4;z++)CityEconomy.require(l.hasChunk(x,z),"请先靠近城市加载全部范围，再落成；不会强制加载");builds.put(c.id,new Build(c.revision,new CityScanCursor(CityLoadedChunks.scanBoxes(l,c.bounds))));state.cities.computeIfAbsent(c.id,k->new Plan()).status="正在分批记录落成方块";setDirty();}
 public static void tick(MinecraftServer s){var d=get(s);var data=CityData.get(s);var e=CityEconomy.get(s);long now=s.overworld().getGameTime();
  d.capture(s,data);
  if(d.state.cities.isEmpty())return;var ids=new ArrayList<>(d.state.cities.keySet());UUID id=ids.get(Math.floorMod(d.cityCursor++,ids.size()));var c=data.cities.get(id);if(c==null)return; /* Preserve registration when the city registry is temporarily unavailable; explicit deletion is separate. */var p=d.state.cities.get(id);if(c.works.finalized)return;var l=CityEconomy.level(s,c);
  if(p.collective&&!p.baseline.isEmpty()){var list=d.positions.computeIfAbsent(id,k->new ArrayList<>(p.baseline.keySet()));for(int i=0;i<Math.min(128,list.size());i++){if(p.foodScan>=list.size()){p.healthyPlots=p.foodPlots;p.foodScan=0;p.foodPlots=0;}long key=list.get(p.foodScan++);var pos=BlockPos.of(key);var b=d.decoded.computeIfAbsent(p.baseline.get(key),CityMaintenance::decode);if(c.includes(pos)&&b.is(Blocks.WHEAT)&&(p.ready.contains(key)||(!p.damaged.contains(key)&&(!l.hasChunkAt(pos)||(l.getBlockState(pos).is(Blocks.WHEAT)&&l.getBlockState(pos.below()).is(Blocks.FARMLAND))))))p.foodPlots++;}}
  if(p.collective&&now>=p.nextFood){p.nextFood=now+1200;d.food(s,c,p);d.setDirty();}
  if(!p.enabled||p.baseline.isEmpty()||d.builds.containsKey(id))return;
  var workers=d.state.workers.entrySet().stream().filter(v->v.getValue().enabled&&v.getValue().city.equals(id)&&c.residents.contains(v.getKey())&&available(l,c,v.getKey())).sorted(Comparator.<Map.Entry<UUID,Worker>>comparingInt(v->v.getValue().priority).reversed().thenComparing(v->v.getKey().toString())).toList();
  for(var entry:workers){var worker=entry.getValue();long elapsed=worker.workClock==0?0:Math.max(0,now-worker.workClock);worker.workClock=now;if(!WorkHours.active(s,c,entry.getKey())&&worker.next>0)worker.next+=elapsed;}
  Set<String> assigned=new HashSet<>();for(var w:workers){assigned.addAll(w.getValue().blocks);if(w.getValue().next==0){w.getValue().next=now+Math.max(20,72000/w.getValue().perHour);d.setDirty();}}
  var readyWorkers=workers.stream().filter(v->v.getValue().next<=now&&WorkHours.active(s,c,v.getKey())).toList();
  var points=d.positions.computeIfAbsent(id,k->new ArrayList<>(p.baseline.keySet()));int repaired=0;for(int i=0;i<Math.min(256,points.size());i++){long packed=points.get(Math.floorMod(p.scan++,points.size()));var pos=BlockPos.of(packed);if(!c.includes(pos))continue;boolean loaded=l.hasChunkAt(pos);if(!loaded&&!p.damaged.contains(packed))continue;var target=d.decoded.computeIfAbsent(p.baseline.get(packed),CityMaintenance::decode);var actual=loaded?l.getBlockState(pos):Blocks.AIR.defaultBlockState();if(loaded&&same(actual,target)){if(p.damaged.remove(packed)){p.ready.remove(packed);d.setDirty();}continue;}if(p.damaged.add(packed))d.setDirty();String block=BuiltInRegistries.BLOCK.getKey(target.getBlock()).toString();
   // Never overwrite a live container or entomb an entity. Inventory is not part of the baseline.
   boolean blocked=loaded&&(l.getBlockEntity(pos)!=null||(!target.getCollisionShape(l,pos).isEmpty()&&!l.getEntities(null,new net.minecraft.world.phys.AABB(pos)).isEmpty()));
   if(p.ready.contains(packed)){if(loaded&&!blocked){var restore=target.getBlock() instanceof CropBlock crop?crop.getStateForAge(0):target;if(restore.canSurvive(l,pos)&&l.setBlock(pos,restore,2)){p.ready.remove(packed);p.damaged.remove(packed);d.setDirty();CityService.invalidate(c);if(++repaired>=2)break;}}continue;}
   for(var entry:readyWorkers){var w=entry.getValue();if(!matches(w,block,assigned))continue;if(w.next==0){w.next=now+Math.max(20,72000/w.perHour);d.setDirty();continue;}if(now<w.next)continue;
    var restore=target.getBlock() instanceof CropBlock crop?crop.getStateForAge(0):target;boolean project=loaded&&!blocked&&restore.canSurvive(l,pos);if(!CityHousing.repairMaterial(s,c,pos,restore))continue;if(!project||l.setBlock(pos,restore,2)){CityHousing.repaired(s,c,pos);if(project)p.damaged.remove(packed);else p.ready.add(packed);w.next=now+Math.max(20,72000/w.perHour);p.repaired++;p.status="已修补"+p.repaired+"格；未加载区域等待靠近";d.setDirty();CityService.invalidate(c);repaired++;}else CityHousing.refundMaterial(c,pos,restore);break;
   }if(repaired>=2)break;
  }
 }
 private void capture(MinecraftServer s,CityData data){var d=this;
  if(!d.builds.isEmpty()){var entry=d.builds.entrySet().iterator().next();var c=data.cities.get(entry.getKey());var b=entry.getValue();var p=d.state.cities.get(entry.getKey());if(c==null||c.revision!=b.revision){d.builds.remove(entry.getKey());if(p!=null)p.status="范围变化，记录取消，旧基准保留";return;}var l=CityEconomy.level(s,c);b.cursor.step(l,512,pos->{if(c.includes(pos)){var block=l.getBlockState(pos);if(!block.isAir())b.blocks.put(pos.asLong(),encode(block));}},air->{});if(b.cursor.lostChunk){p.status="区块已卸载，旧基准保留；靠近后重新记录";d.builds.remove(c.id);return;}if(b.cursor.done()){if(b.blocks instanceof CityBlockStore store)store.compact();p.baseline=b.blocks;p.damaged.clear();p.ready.clear();p.scan=0;p.foodScan=0;p.foodPlots=0;p.healthyPlots=0;p.status="已落成："+b.blocks.size()+"格；按职业逐步修补";d.positions.remove(c.id);d.builds.remove(c.id);d.state.revision++;d.setDirty();}return;}
 }
 void food(MinecraftServer s,CityData.City c,Plan p){var e=CityEconomy.get(s);var l=CityEconomy.level(s,c);long farmers=state.workers.entrySet().stream().filter(v->v.getValue().enabled&&v.getValue().role.equals("农民")&&v.getValue().city.equals(c.id)&&c.residents.contains(v.getKey())&&available(l,c,v.getKey())&&WorkHours.active(s,c,v.getKey())).count();if(farmers==0)return;
  // City-wide plots, never a local work radius; cache baseline damage conservatively when unloaded.
  int plots=p.healthyPlots;
  long capacity=Math.min(plots,farmers*80);p.foodCredit+=capacity*1200;int wheat=(int)(p.foodCredit/72000);p.foodCredit%=72000;
  try{var box=CityEconomy.warehouse(l,c,p.warehouse);var slots=new CityEconomy.Slots(box);if(wheat>0)slots.add("minecraft:wheat",wheat);slots.commit();var contents=CitySimulation.contents(box);int bread=Math.min(64,contents.getOrDefault("minecraft:wheat",0)/3);if(bread>0){var cook=new CityEconomy.Slots(box);cook.remove("minecraft:wheat",bread*3);cook.add("minecraft:bread",bread);cook.commit();}p.status="集体口粮：有效麦田"+plots+"格，农民"+farmers+"人；每3小麦制1面包";}catch(IllegalArgumentException ex){p.status="集体口粮暂停："+ex.getMessage();}
 }
 static void recordHouse(MinecraftServer s,CityData.City c,CityRegistry.Building building,Map<Long,String> blocks){var d=get(s);var plan=d.state.cities.computeIfAbsent(c.id,k->new Plan());if(plan.baseline instanceof CityBlockStore store)store.removeWithin(building.bounds());else plan.baseline.keySet().removeIf(v->building.bounds().contains(BlockPos.of(v)));plan.baseline.putAll(blocks);plan.damaged.retainAll(plan.baseline.keySet());plan.ready.retainAll(plan.baseline.keySet());d.positions.remove(c.id);d.setDirty();}
 static void enableDataCity(MinecraftServer server,CityData.City c){var e=CityEconomy.get(server);var simulation=e.state.simulation.computeIfAbsent(c.id,k->new CitySimulation.Policy());simulation.enabled=true;simulation.emigrateAfter=0;var l=CityEconomy.level(server,c);for(UUID npc:c.residents)if(l.getEntity(npc) instanceof net.minecraft.world.entity.LivingEntity living)CitySimulation.remember(e,c,simulation,living,false);e.setDirty();}
 public static void request(ServerPlayer player,CityNetwork.Request r){var d=get(player.server);try{CityEconomy.require(player.hasPermissions(2),"需要管理员权限");var c=CityData.get(player.server).require(UUID.fromString(r.city()));CityEconomy.require(c.dimension.equals(player.level().dimension().location().toString()),"城市不在当前维度");
  if(r.op().equals("maintworker")){UUID npc=UUID.fromString(r.value());CityNpcBridge.editing(player,npc);CityEconomy.require(c.residents.contains(npc),"NPC未绑定此城");d.workerSnapshot(player,c,npc,"");return;}
  if(r.op().equals("maintsave")){var json=JsonParser.parseString(r.value()).getAsJsonObject();UUID npc=UUID.fromString(json.get("npc").getAsString());CityNpcBridge.editing(player,npc);CityEconomy.require(c.residents.contains(npc)&&r.revision()==d.state.revision,"数据变化，请重读");exact(json.get("worker"));var w=CityEconomy.JSON.fromJson(json.get("worker"),Worker.class);CityEconomy.require(c.id.equals(w.city),"不能修改其他城市");var check=new State();check.workers.put(npc,w);validate(check);w.next=player.server.overworld().getGameTime()+Math.max(20,72000/w.perHour);d.state.workers.put(npc,w);enableDataCity(player.server,c);d.state.revision++;d.setDirty();d.workerSnapshot(player,c,npc,"职业与修补设置已保存");return;}
  CityEconomy.require(player.getMainHandItem().getItem()==CityMod.ATLAS.get()||BuiltInRegistries.ITEM.getKey(player.getMainHandItem().getItem()).toString().equals("customnpcs:npcwand"),"请手持信息魔杖或NPC魔杖");CityService.checkEditor(player,c,r.revision());
  if(r.op().equals("maintcomplete"))d.start(player.server,c);
  else if(r.op().equals("maintpause")){var p=d.state.cities.computeIfAbsent(c.id,k->new Plan());p.enabled=!p.enabled;d.state.revision++;d.setDirty();}
  else if(r.op().equals("maintcollective")){var p=d.state.cities.computeIfAbsent(c.id,k->new Plan());if(r.value().equals("off")){p.collective=false;}else{UUID warehouse=UUID.fromString(r.value());CityEconomy.require(c.warehouses.containsKey(warehouse)&&CityEconomy.get(player.server).state.warehouseOwners.containsKey(warehouse),"请选择本城已登记经营粮仓");p.warehouse=warehouse;p.collective=true;enableDataCity(player.server,c);p.nextFood=player.server.overworld().getGameTime()+1200;var e=CityEconomy.get(player.server);for(UUID npc:c.residents){var life=e.state.living.computeIfAbsent(npc,k->CityLiving.defaults(c.id,npc));e.state.accounts.putIfAbsent(CityEconomy.person(npc),0L);life.basicMode=true;life.enabled=true;life.basicWarehouse=warehouse;life.periodTicks=1200;life.nextTick=p.nextFood;var n=new CityLiving.Need();n.item="minecraft:bread";life.basket=new ArrayList<>(List.of(n));}e.invalidateIndexes();e.state.revision++;e.setDirty();}d.state.revision++;d.setDirty();}
  else CityEconomy.require(r.op().equals("maintview"),"未知修补操作");d.citySnapshot(player,c,"");
 }catch(Exception ex){player.sendSystemMessage(Component.literal("[职业修补] "+ex.getMessage()));}}
 void workerSnapshot(ServerPlayer player,CityData.City c,UUID npc,String message){var w=state.workers.getOrDefault(npc,new Worker());if(w.city==null)w.city=c.id;var t=new CompoundTag();t.putBoolean("MaintenanceWorker",true);t.putString("City",c.id.toString());t.putString("Npc",npc.toString());t.putString("Worker",CityEconomy.JSON.toJson(w));t.putLong("Revision",state.revision);t.putString("Message",message);PacketDistributor.sendToPlayer(player,new CityNetwork.Snapshot(t));}
 void citySnapshot(ServerPlayer player,CityData.City c,String message){var p=state.cities.getOrDefault(c.id,new Plan());var t=new CompoundTag();t.putBoolean("MaintenanceCity",true);t.putString("City",c.id.toString());t.putString("Name",c.name);t.putLong("Revision",c.revision);t.putBoolean("Enabled",p.enabled);t.putBoolean("Collective",p.collective);t.putString("Warehouse",String.valueOf(p.warehouse));t.putInt("Blocks",p.baseline.size());t.putString("Status",p.status);t.putString("Message",message);var a=new JsonArray();for(var w:c.warehouses.values())if(CityEconomy.get(player.server).state.warehouseOwners.containsKey(w.id())){var j=new JsonObject();j.addProperty("id",w.id().toString());j.addProperty("name",w.name());a.add(j);}t.putString("Warehouses",a.toString());PacketDistributor.sendToPlayer(player,new CityNetwork.Snapshot(t));}
 public static void register(com.mojang.brigadier.CommandDispatcher<net.minecraft.commands.CommandSourceStack> dispatcher){
  var root=net.minecraft.commands.Commands.literal("citymaintenance").requires(x->x.hasPermission(2));
  root.then(net.minecraft.commands.Commands.literal("complete").then(net.minecraft.commands.Commands.argument("city",com.mojang.brigadier.arguments.StringArgumentType.word()).executes(ctx->{try{var server=ctx.getSource().getServer();get(server).start(server,CityData.get(server).require(UUID.fromString(com.mojang.brigadier.arguments.StringArgumentType.getString(ctx,"city"))));ctx.getSource().sendSuccess(()->Component.literal("落成记录已开始，分批完成"),false);return 1;}catch(Exception ex){ctx.getSource().sendFailure(Component.literal(ex.getMessage()));return 0;}})));
  for(String op:List.of("export","apply")){var argument=net.minecraft.commands.Commands.argument("file",com.mojang.brigadier.arguments.StringArgumentType.word());
   if(op.equals("export"))argument.executes(ctx->exchange(ctx.getSource(),com.mojang.brigadier.arguments.StringArgumentType.getString(ctx,"file"),-1));
   else argument.then(net.minecraft.commands.Commands.argument("revision",com.mojang.brigadier.arguments.LongArgumentType.longArg(0)).executes(ctx->exchange(ctx.getSource(),com.mojang.brigadier.arguments.StringArgumentType.getString(ctx,"file"),com.mojang.brigadier.arguments.LongArgumentType.getLong(ctx,"revision"))));root.then(net.minecraft.commands.Commands.literal(op).then(argument));
  }dispatcher.register(root);
 }
 static int exchange(net.minecraft.commands.CommandSourceStack source,String name,long revision){try{CityEconomy.require(name.matches("[A-Za-z0-9_-]{1,64}"),"文件名无效");var d=get(source.getServer());var dir=source.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("city_settlements/maintenance");java.nio.file.Files.createDirectories(dir);var file=dir.resolve(name+".json");if(revision<0)java.nio.file.Files.writeString(file,CityEconomy.JSON.toJson(d.state));else{CityEconomy.require(revision==d.state.revision&&java.nio.file.Files.size(file)<=32*1024*1024,"版本变化或文件超过32MB");var input=JsonParser.parseString(java.nio.file.Files.readString(file));exact(input);var next=CityEconomy.JSON.fromJson(input,State.class);validate(next);CityEconomy.require(next.revision==revision,"文件版本不符");var cities=CityData.get(source.getServer());for(var entry:next.cities.entrySet()){var c=cities.require(entry.getKey());for(long pos:entry.getValue().baseline.keySet())CityEconomy.require(c.includes(BlockPos.of(pos)),"落成方块越出城市");if(entry.getValue().collective)CityEconomy.require(c.warehouses.containsKey(entry.getValue().warehouse),"公共仓库不在本城");}for(var entry:next.workers.entrySet())CityEconomy.require(cities.require(entry.getValue().city).residents.contains(entry.getKey()),"职业NPC未登记本城");java.nio.file.Files.writeString(dir.resolve(name+"-previous.json"),CityEconomy.JSON.toJson(d.state));next.revision++;d.state=next;d.positions.clear();d.decoded.clear();d.builds.clear();d.setDirty();}source.sendSuccess(()->Component.literal("修补数据"+(revision<0?"已导出":"已应用")+"，版本="+d.state.revision),false);return 1;}catch(Exception ex){source.sendFailure(Component.literal("[职业修补] "+ex.getMessage()));return 0;}}

}

